module fractional_n_pll (
    input wire clk_ref,
    input wire reset,
    input wire [7:0] fractional_n,
    output reg clk_out
);

    reg [31:0] counter;
    reg [7:0] divider;

    always @(posedge clk_ref or posedge reset) begin
        if (reset) begin
            counter <= 0;
            clk_out <= 0;
        end else begin
            counter <= counter + 1;
            if (counter >= fractional_n) begin
                clk_out <= ~clk_out; // Toggle output clock
                counter <= 0; // Reset counter
            end
        end
    end

endmodule

