module pll(input wire clk, input wire reset, input wire freq_in, output reg freq_out);
    reg [3:0] phase_counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            phase_counter <= 4'b0000;
            freq_out <= 0;
        end else begin
            phase_counter <= phase_counter + 1;
            freq_out <= freq_in ^ phase_counter[3]; // phase adjustment using XOR
        end
    end
endmodule

