module uart_transmitter (
    input wire clk,
    input wire reset,
    input wire [7:0] data_in,
    input wire send,
    output reg tx,
    output reg busy
);

    reg [3:0] bit_index;
    reg [10:0] shift_reg; // 1 start bit + 8 data bits + 1 stop bit
    reg [15:0] baud_counter;

    parameter BAUD_RATE = 9600; // Adjust as needed
    parameter CLOCK_FREQ = 50000000; // Adjust as needed
    parameter BIT_PERIOD = CLOCK_FREQ / BAUD_RATE;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            tx <= 1; // Idle state is high
            busy <= 0;
            bit_index <= 0;
            baud_counter <= 0;
            shift_reg <= 0;
        end else if (send && !busy) begin
            busy <= 1;
            shift_reg <= {1'b1, data_in, 1'b0}; // Stop bit + data + start bit
            bit_index <= 0;
        end else if (busy) begin
            baud_counter <= baud_counter + 1;
            if (baud_counter == BIT_PERIOD - 1) begin
                baud_counter <= 0;
                tx <= shift_reg[bit_index];
                bit_index <= bit_index + 1;
                if (bit_index == 10) begin // 10 bits transmitted
                    busy <= 0;
                end
            end
        end
    end
endmodule

