module serializer_16bit (
    input clk,
    input reset,
    input [15:0] parallel_in,
    output reg serial_out
);
    reg [3:0] bit_counter; // To count from 0 to 15

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_counter <= 4'b0000;
            serial_out <= 1'b0;
        end else begin
            if (bit_counter < 4'd16) begin
                serial_out <= parallel_in[bit_counter];
                bit_counter <= bit_counter + 1;
            end
        end
    end
endmodule

