module noise_suppression #(parameter N = 4) (  
    input clk,  
    input rst,  
    input [1:0] signal_in,  
    output reg [1:0] signal_out  
);  
    reg [1:0] samples [0:N-1];  
    integer i;  
    reg [3:0] sum;  
    reg [1:0] avg;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            for (i = 0; i < N; i = i + 1)  
                samples[i] <= 2'b00;  
            signal_out <= 2'b00;  
        end else begin  
            // Shift samples  
            for (i = N-1; i > 0; i = i - 1)  
                samples[i] <= samples[i-1];  
            samples[0] <= signal_in;  

            // Calculate sum  
            sum = 0;  
            for (i = 0; i < N; i = i + 1)  
                sum = sum + samples[i];  
            avg = sum / N;  
            signal_out <= avg;  
        end  
    end  
endmodule

