module echo_canceller #(parameter TAP_LENGTH = 5) (  
    input clk,  
    input rst,  
    input signed [15:0] x_in,  
    input signed [15:0] d_in,  
    output reg signed [15:0] y_out  
);  
    reg signed [15:0] taps [0:TAP_LENGTH-1];  
    integer i;  
    reg signed [31:0] accumulator;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            for (i = 0; i < TAP_LENGTH; i = i + 1)  
                taps[i] <= 0;  
            y_out <= 0;  
        end else begin  
            // Shift the taps  
            for (i = TAP_LENGTH-1; i > 0; i = i - 1)  
                taps[i] <= taps[i-1];  
            taps[0] <= x_in;  

            // Compute the output using the FIR filter  
            accumulator = 0;  
            for (i = 0; i < TAP_LENGTH; i = i + 1)  
                accumulator = accumulator + taps[i] * d_in;  
            y_out <= accumulator[15:0];  
        end  
    end  
endmodule

