module RLE_Encoder (  
    input clk,  
    input rst,  
    input data_in,  
    output reg [1:0] value_out,  
    output reg [3:0] count_out,  
    output reg valid  
);  
    reg [1:0] state;  
    reg [3:0] count;  
    reg last_bit;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= 0;  
            count <= 0;  
            last_bit <= 0;  
            valid <= 0;  
        end else begin  
            case (state)  
                0: begin // Start state  
                    last_bit <= data_in;  
                    count <= 1;  
                    state <= 1;  
                    valid <= 0;  
                end  
                1: begin // Counting state  
                    if (data_in == last_bit) begin  
                        count <= count + 1;  
                    end else begin  
                        value_out <= last_bit;  
                        count_out <= count;  
                        valid <= 1;  
                        last_bit <= data_in;  
                        count <= 1;  
                        state <= 2;  
                    end  
                end  
                2: begin // Waiting for next input  
                    if (data_in != last_bit) begin  
                        state <= 1;  
                        valid <= 0;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

