module uart_transmitter #(parameter BAUD_RATE = 9600, DATA_BITS = 8) (  
    input wire clk,  
    input wire reset,  
    input wire [DATA_BITS-1:0] data_in,  
    input wire transmit_en,  
    output reg tx,  
    output reg busy  
);  
    localparam START_BIT = 1'b0;  
    localparam STOP_BIT = 1'b1;  
    localparam CLOCK_DIV = 50_000_000 / BAUD_RATE; // Assuming a 50 MHz clock  
    reg [3:0] bit_counter;  
    reg [15:0] clk_counter;  
    reg [DATA_BITS-1:0] shift_reg;  
    reg state;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            tx <= 1;  
            busy <= 0;  
            bit_counter <= 0;  
            clk_counter <= 0;  
            state <= 0;  
        end else begin  
            if (transmit_en && !busy) begin  
                busy <= 1;  
                shift_reg <= data_in;  
                bit_counter <= 0;  
                clk_counter <= 0;  
                state <= 1; // Start transmission  
            end  

            if (state) begin  
                clk_counter <= clk_counter + 1;  
                if (clk_counter >= CLOCK_DIV - 1) begin  
                    clk_counter <= 0;  
                    if (bit_counter == 0) begin  
                        tx <= START_BIT; // Send start bit  
                    end else if (bit_counter <= DATA_BITS) begin  
                        tx <= shift_reg[bit_counter - 1]; // Send data bits  
                    end else begin  
                        tx <= STOP_BIT; // Send stop bit  
                    end  

                    bit_counter <= bit_counter + 1;  
                    if (bit_counter == DATA_BITS + 1) begin  
                        busy <= 0;  
                        state <= 0;  
                    end  
                end  
            end  
        end  
    end  
endmodule

