module ButterworthFilter (  
    input wire clk,  
    input wire reset,  
    input wire signed [3:0] x,  
    output reg signed [3:0] y  
);  
    reg signed [3:0] y_prev1, y_prev2;  
    reg signed [3:0] a0, a1, a2;  
    reg signed [3:0] b0;  

    initial begin  
        a0 = 4'sd1;  
        a1 = 4'sd2;  
        a2 = 4'sd1;  
        b0 = 4'sd1;  
    end  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            y <= 4'sd0;  
            y_prev1 <= 4'sd0;  
            y_prev2 <= 4'sd0;  
        end else begin  
            y <= (b0 * x + a1 * y_prev1 + a2 * y_prev2) >>> 2;  
            y_prev2 <= y_prev1;  
            y_prev1 <= y;  
        end  
    end  
endmodule

