module pll(input wire clk_ref, output reg clk_out);  
    reg [3:0] phase_error;  
    reg [3:0] vco_count;  
    initial begin  
        clk_out = 0;  
        phase_error = 0;  
        vco_count = 0;  
    end  
    always @(posedge clk_ref) begin  
        // Simulate phase detection  
        phase_error <= phase_error + (clk_out ? -1 : 1);  
        // Simulate low-pass filtering  
        if (phase_error > 2) begin  
            phase_error <= phase_error - 1;  
        end else if (phase_error < -2) begin  
            phase_error <= phase_error + 1;  
        end  
        // Simulate VCO  
        vco_count <= vco_count + (phase_error[0] ? 1 : 0);  
        clk_out <= (vco_count[1] == 1);  
    end  
endmodule

