module iir_filter (
    input clk,
    input rst,
    input signed [15:0] x, // Input sample
    output reg signed [15:0] y // Output sample
);
    reg signed [15:0] x1, x2; // Previous input samples
    reg signed [15:0] y1, y2; // Previous output samples

    // Coefficients (fixed-point representation)
    parameter signed [15:0] b0 = 16'h0A00; // 0.625
    parameter signed [15:0] b1 = 16'h1400; // 1.25
    parameter signed [15:0] b2 = 16'h0A00; // 0.625
    parameter signed [15:0] a1 = 16'hF600; // -0.875
    parameter signed [15:0] a2 = 16'h0C00; // 0.75

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y <= 16'h0000;
            x1 <= 16'h0000;
            x2 <= 16'h0000;
            y1 <= 16'h0000;
            y2 <= 16'h0000;
        end else begin
            // IIR filter equation
            y <= (b0 * x + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2) >>> 10; // Scale down
            // Shift samples
            x2 <= x1;
            x1 <= x;
            y2 <= y1;
            y1 <= y;
        end
    end
endmodule

