module serializer_16bit (  
    input clk,  
    input reset,  
    input enable,  
    input [15:0] data_in,  
    output reg serialized_out  
);  
    reg [15:0] shift_reg;  
    integer count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            shift_reg <= 16'b0;  
            serialized_out <= 1'b0;  
            count <= 0;  
        end else if (enable) begin  
            if (count < 16) begin  
                serialized_out <= shift_reg[15];  
                shift_reg <= {shift_reg[14:0], 1'b0};  
                count <= count + 1;  
            end else begin  
                serialized_out <= 1'b0;  // After all bits have been serialized  
            end  
        end else begin  
            serialized_out <= 1'b0;  
        end  
    end  

    always @(posedge clk) begin  
        if (enable) begin  
            shift_reg <= data_in;  
        end  
    end  
endmodule

