module MersenneTwister #(parameter WIDTH = 32, parameter N = 624, parameter M = 397, parameter MATRIX_A = 32'h9908B0DF, parameter UPPER_MASK = 32'hFFFFFFFF, parameter LOWER_MASK = 32'h7FFFFFFF) (  
    input clk,  
    input rst,  
    input [WIDTH-1:0] seed,  
    input gen,  
    output reg [WIDTH-1:0] random_number  
);  

reg [WIDTH-1:0] mt [0:N-1];  
reg [WIDTH-1:0] index;  

always @(posedge clk or posedge rst) begin  
    if (rst) begin  
        index <= 0;  
        mt[0] <= seed;  
        for (integer i = 1; i < N; i = i + 1)  
            mt[i] <= (1812433253 * (mt[i-1] ^ (mt[i-1] >> 30)) + i);  
    end else if (gen) begin  
        if (index == 0) begin  
            for (integer i = 0; i < N-M; i = i + 1) begin  
                mt[i] <= mt[i+M] ^ ((mt[i] & UPPER_MASK) | (mt[i+1] & LOWER_MASK)) >> 1 ^ (mt[i+1] & 1 ? MATRIX_A : 0);  
            end  
            for (integer i = N-M; i < N-1; i = i + 1) begin  
                mt[i] <= mt[i+M-N] ^ ((mt[i] & UPPER_MASK) | (mt[i+1] & LOWER_MASK)) >> 1 ^ (mt[i+1] & 1 ? MATRIX_A : 0);  
            end  
            mt[N-1] <= mt[M-1] ^ ((mt[N-1] & UPPER_MASK) | (mt[0] & LOWER_MASK)) >> 1 ^ (mt[0] & 1 ? MATRIX_A : 0);  
        end  
        random_number <= mt[index];  
        index <= (index + 1) % N;  
    end  
end  
endmodule

