        if (rst) begin  
            state <= 2'b00;  
            encoded_out <= 2'b00;  
        end else begin  
            state <= {data_in, state[1]};  
            encoded_out <= {state[0] ^ state[1], state[1]};  
        end  
    end  

    // Simple decoding logic (for illustration purposes)  
    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            decoded_out <= 1'b0;  
        end else begin  
            decoded_out <= encoded_out[1];  
        end  
    end  
endmodule

