module pulse_generator(
    input wire CLK,
    input wire RESET,
    input wire START,
    input wire [3:0] WIDTH, // pulse width in clock cycles
    output reg PULSE
);
    reg [3:0] count;

    always @(posedge CLK or posedge RESET) begin
        if (RESET) begin
            PULSE <= 0;
            count <= 0;
        end else if (START) begin
            PULSE <= 1;
            count <= WIDTH;
        end else if (count > 0) begin
            count <= count - 1;
            if (count == 1) begin
                PULSE <= 0;
            end
        end
    end
endmodule

