module watchdog_timer #(parameter TIMEOUT_PERIOD = 10) (  
    input wire clk,  
    input wire reset,  
    output reg timeout_signal  
);  
    reg [3:0] counter;  
    reg state; // 0: normal, 1: timeout  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            timeout_signal <= 0;  
            state <= 0;  
        end else begin  
            if (state == 0) begin // Normal operation  
                if (counter < TIMEOUT_PERIOD) begin  
                    counter <= counter + 1;  
                end else begin  
                    state <= 1; // Transition to timeout state  
                    timeout_signal <= 1;  
                end  
            end  
        end  
    end  
endmodule

