module viterbi_decoder (  
    input clk,  
    input reset,  
    input [1:0] input_bits,  
    output reg [1:0] decoded_output  
);  
    reg [1:0] state;  
    reg [1:0] next_state;  

    // Define state transition logic  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= 2'b00;  
        end else begin  
            state <= next_state;  
        end  
    end  

    // Next state logic and output logic  
    always @(*) begin  
        case (state)  
            2'b00: begin  
                case (input_bits)  
                    2'b00: begin  
                        next_state = 2'b00;  
                        decoded_output = 2'b00;  
                    end  
                    2'b01: begin  
                        next_state = 2'b01;  
                        decoded_output = 2'b01;  
                    end  
                    2'b10: begin  
                        next_state = 2'b10;  
                        decoded_output = 2'b10;  
                    end  
                    2'b11: begin  
                        next_state = 2'b11;  
                        decoded_output = 2'b11;  
                    end  
                endcase  
            end  
            2'b01: begin  
                // Define next state and output for state 01  
                // Add your logic here  
