                // Define next state and output for state 10  
                // Add your logic here  
            end  
            2'b11: begin  
                // Define next state and output for state 11  
                // Add your logic here  
            end  
            default: begin  
                next_state = 2'b00;  
                decoded_output = 2'b00;  
            end  
        endcase  
    end  
endmodule

