module rrt_algorithm(  
    input clk,  
    input reset,  
    input [7:0] start_x,  
    input [7:0] start_y,  
    input [7:0] target_x,  
    input [7:0] target_y,  
    output reg [7:0] curr_x,  
    output reg [7:0] curr_y,  
    output reg done  
);  
    reg [3:0] state;  
    parameter IDLE = 0, SEARCH = 1, CONNECT = 2, DONE = 3;  
    integer iterations;  
    parameter MAX_ITERATIONS = 100;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            curr_x <= start_x;  
            curr_y <= start_y;  
            done <= 0;  
            iterations <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    state <= SEARCH;  
                end  
                SEARCH: begin  
                    if (iterations < MAX_ITERATIONS) begin  
                        // Generate a random point (for simulation, we can just increment)  
                        // Normally, you'd generate a random point here in an actual implementation  
                        iterations <= iterations + 1;  
                        state <= CONNECT;  
                    end else begin  
                        done <= 1;  
                        state <= DONE;  
                    end  
                end  
                CONNECT: begin  
                    // Simulate the connecting logic (for simplicity, increment towards target)  
                    if (curr_x < target_x) curr_x <= curr_x + 1;  
                    if (curr_y < target_y) curr_y <= curr_y + 1;  
                    if (curr_x == target_x && curr_y == target_y) begin  
                        done <= 1;  
                        state <= DONE;  
                    end else begin  
                        state <= SEARCH;  
                    end  
                end  
                DONE: begin  
                    // Stay in DONE state  
                    state <= DONE;  
                end  
            endcase  
        end  
    end  
endmodule

