module fractional_n_pll (
    input wire clk_in,
    input wire [7:0] fraction,
    input wire reset,
    output reg clk_out
);
    reg [15:0] counter;
    reg [15:0] vco_freq;

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            counter <= 0;
            vco_freq <= 0;
            clk_out <= 0;
        end else begin
            if (counter >= (256 - fraction)) begin
                clk_out <= ~clk_out;
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
            vco_freq <= vco_freq + fraction;
        end
    end
endmodule

